package engine

// Source timestamps are unsigned milliseconds; subtraction unfolds their wrap.
// RTP timestamps retain a random origin generated by Pion's packetizer.
type sourceVideoClock struct {
	origin      uint32
	initialized bool
	last        uint32
	elapsed     uint64
}

func (c *sourceVideoClock) timestamp(ms uint32) uint32 {
	if !c.initialized {
		c.initialized = true
		c.last = ms
		return c.origin
	}
	delta := int32(ms - c.last)
	if delta > 0 {
		c.elapsed += uint64(delta) * 90
		c.last = ms
	} else {
		c.elapsed++
	}
	return c.origin + uint32(c.elapsed)
}
